//! Pins the wire format of the IPC DTOs whose TS bindings are generated by
//! ts-rs into `src/lib/contracts/generated/`.
//!
//! The enum variants replaced string fields, so each one must serialize to
//! the exact literal the frontend already receives.

use kokobrain_lib::commands::history::{DiffLine, DiffLineType};
use kokobrain_lib::commands::vault::{FileNode, ScanSource};
use kokobrain_lib::semantic::types::SemanticPhase;
use kokobrain_lib::vault::index::UpdateResult;
use kokobrain_lib::vault::task::TaskMetadata;
use serde_json::{json, to_value};
use ts_rs::{Config, TS};

#[test]
fn semantic_phase_serializes_to_the_legacy_literals() {
	assert_eq!(to_value(SemanticPhase::DownloadingReranker).unwrap(), json!("downloading-reranker"));
	assert_eq!(to_value(SemanticPhase::Downloading).unwrap(), json!("downloading"));
	assert_eq!(to_value(SemanticPhase::Chunking).unwrap(), json!("chunking"));
	assert_eq!(to_value(SemanticPhase::Embedding).unwrap(), json!("embedding"));
}

#[test]
fn diff_line_type_serializes_to_the_legacy_literals() {
	assert_eq!(to_value(DiffLineType::Equal).unwrap(), json!("equal"));
	assert_eq!(to_value(DiffLineType::Delete).unwrap(), json!("delete"));
	assert_eq!(to_value(DiffLineType::Insert).unwrap(), json!("insert"));
}

#[test]
fn scan_source_serializes_to_the_legacy_literals() {
	assert_eq!(to_value(ScanSource::FullScan).unwrap(), json!("full_scan"));
	assert_eq!(to_value(ScanSource::Cache).unwrap(), json!("cache"));
	assert_eq!(to_value(ScanSource::CacheReconciled).unwrap(), json!("cache_reconciled"));
}

/// The TS file ts-rs writes for `T`, read through the same env config
/// `cargo test` uses, so the assertion does not depend on test order.
fn generated<T: TS + 'static>() -> String {
	T::export_to_string(&Config::from_env()).unwrap()
}

#[test]
fn file_node_without_children_has_no_children_key() {
	let node = FileNode {
		name: "a.md".into(),
		path: "/v/a.md".into(),
		is_directory: false,
		children: None,
		modified_at: None,
		created_at: None,
	};
	let value = to_value(&node).unwrap();
	assert!(value.get("children").is_none(), "{value}");
	assert!(value.get("modifiedAt").is_none(), "{value}");
}

#[test]
fn generated_file_node_declares_optional_fields_without_null() {
	let ts = generated::<FileNode>();
	assert!(ts.contains("children?: Array<FileNode>"), "{ts}");
	assert!(ts.contains("modifiedAt?: number"), "{ts}");
	assert!(!ts.contains("| null"), "{ts}");
}

#[test]
fn generated_task_metadata_declares_due_date_without_null() {
	let ts = generated::<TaskMetadata>();
	assert!(ts.contains("dueDate?: string,"), "{ts}");
	assert!(!ts.contains("| null"), "{ts}");
}

#[test]
fn generated_large_ints_are_numbers() {
	let ts = generated::<UpdateResult>();
	assert!(ts.contains("version: number"), "{ts}");
	assert!(!ts.contains("bigint"), "{ts}");
}

#[test]
fn generated_enum_fields_are_literal_unions() {
	let ts = generated::<SemanticPhase>();
	assert!(ts.contains(r#""downloading-reranker""#), "{ts}");
	let ts = generated::<DiffLine>();
	assert!(ts.contains("type: DiffLineType"), "{ts}");
	assert!(ts.contains(r#"import type { DiffLineType } from "./DiffLineType.js";"#), "{ts}");
}
